import { AreaChart, BarChart, Heatmap, LineChart, chartFmt, type ChartColor, type ChartStateProps, type HeatmapProps, type ValueFormatter } from '@gntik-ai/charts';
import { Card, CardAction, CardDescription, CardHeader, CardTitle, cn, Toggle, ToggleGroup } from '@gntik-ai/ui';
import { useState, type ReactNode } from 'react';
import { TrendDelta, type KpiDelta } from '../shared/TrendDelta';
import { COST_BY_RANGE, COST_RANGES, type CostPoint } from './fixtures';

export interface ChartCardRange {
  /** Range key ("7d"); also the key into `dataByRange`. */
  value: string;
  label: string;
  /** Optional headline for this range. */
  summary?: { value: string; delta?: KpiDelta };
}

/** Heatmap-only options of a ChartCard with `kind="heatmap"`. */
export type ChartCardHeatmapOptions = Pick<HeatmapProps<object>, 'scale' | 'domain' | 'steps' | 'showValues' | 'rowHeader'>;

export interface ChartCardProps<T extends object> extends ChartStateProps {
  title?: string;
  description?: string;
  ranges?: readonly ChartCardRange[];
  /** Chart rows per range key. */
  dataByRange?: Readonly<Record<string, readonly T[]>>;
  /** X-axis field (heatmap: the row label field). */
  index?: Extract<keyof T, string>;
  /** Series fields, one legend entry each (heatmap: the columns, in order). */
  categories?: ReadonlyArray<Extract<keyof T, string>>;
  /**
   * Chart type. `heatmap` renders an @gntik-ai/charts Heatmap: rows from `index`, columns from
   * `categories`, its hue from `colors[0]`, its colour scale as the legend (`showLegend`) and its
   * cells sized to fill `height`.
   */
  kind?: 'area' | 'line' | 'bar' | 'heatmap';
  /** Heatmap options (scale, domain, steps, showValues, rowHeader). */
  heatmap?: ChartCardHeatmapOptions;
  stacked?: boolean;
  colors?: readonly ChartColor[];
  valueFormatter?: ValueFormatter;
  showLegend?: boolean;
  /** Plot height in px (heatmap: the grid, column labels included). */
  height?: number;
  defaultRange?: string;
  range?: string;
  onRangeChange?: (range: string) => void;
  /** Extra header control (e.g. a MoreMenu), after the range toggle. */
  action?: ReactNode;
  /** Footer content under the chart. */
  footer?: ReactNode;
  /** Heading level of the title, to fit the page outline (default h3). */
  titleAs?: 'h2' | 'h3' | 'h4';
  className?: string;
}

const DEFAULT_CATEGORIES = ['Compute', 'Storage', 'Network'] as const;
const DEFAULT_COLORS: readonly ChartColor[] = ['primary', 'violet', 'cyan'];

/**
 * Chart in a Card: title, optional headline value + delta, a 7d/30d/90d range ToggleGroup, and an
 * @gntik-ai/charts area, line, bar or heatmap chart with its legend (heatmap: its colour scale).
 * The chart states (`state`, `emptyMessage`, `errorMessage`, `onRetry`) and `dataTable` pass through.
 */
export function ChartCard<T extends object = CostPoint>({
  title = 'Infrastructure cost',
  description = 'Spend by resource',
  ranges = COST_RANGES,
  dataByRange = COST_BY_RANGE as unknown as Readonly<Record<string, readonly T[]>>,
  index = 'day' as Extract<keyof T, string>,
  categories = DEFAULT_CATEGORIES as unknown as ReadonlyArray<Extract<keyof T, string>>,
  kind = 'area',
  heatmap,
  stacked = true,
  colors = DEFAULT_COLORS,
  valueFormatter = chartFmt.usd,
  showLegend = true,
  height = 240,
  defaultRange,
  range: rangeProp,
  onRangeChange,
  action,
  footer,
  titleAs = 'h3',
  className,
  state,
  emptyMessage,
  errorMessage,
  onRetry,
  dataTable,
}: ChartCardProps<T>) {
  const [inner, setInner] = useState(defaultRange ?? ranges[0]?.value ?? '');
  const current = rangeProp ?? inner;
  const active = ranges.find((r) => r.value === current) ?? ranges[0];
  const data = (active && dataByRange[active.value]) ?? [];
  const chartLabel = `${title}${active ? `, ${active.label}` : ''}`;
  const states = { state, emptyMessage, errorMessage, onRetry, dataTable };
  const common = { data, index, categories, colors, valueFormatter, showLegend, height, 'aria-label': chartLabel, ...states };
  return (
    <Card className={className}>
      <CardHeader className="pb-2">
        <CardTitle as={titleAs}>{title}</CardTitle>
        {description && <CardDescription>{description}</CardDescription>}
        <CardAction className="flex items-center gap-2">
          {ranges.length > 1 && (
            <ToggleGroup
              aria-label={`${title} range`}
              size="sm"
              value={[current]}
              onValueChange={(v) => {
                const next = v[0];
                if (!next) return;
                setInner(next);
                onRangeChange?.(next);
              }}
            >
              {ranges.map((r) => (
                <Toggle key={r.value} value={r.value} className="font-mono">
                  {r.label}
                </Toggle>
              ))}
            </ToggleGroup>
          )}
          {action}
        </CardAction>
      </CardHeader>
      {active?.summary && (
        <p className="flex flex-wrap items-baseline gap-x-2 px-5" aria-live="polite">
          <span className="text-[24px] font-semibold tracking-tight text-foreground tabular-nums">{active.summary.value}</span>
          {active.summary.delta && <TrendDelta {...active.summary.delta} />}
        </p>
      )}
      <div className={cn('px-3 pb-4 pt-3 sm:px-4', !footer && 'pb-5')}>
        {kind === 'heatmap' ? (
          <Heatmap
            data={data}
            index={index}
            categories={categories}
            color={colors[0] ?? 'primary'}
            valueFormatter={valueFormatter}
            showScale={showLegend}
            height={height}
            aria-label={chartLabel}
            {...heatmap}
            {...states}
            dataTable={dataTable ?? true}
          />
        ) : kind === 'bar' ? (
          <BarChart {...common} stacked={stacked} />
        ) : kind === 'line' ? (
          <LineChart {...common} />
        ) : (
          <AreaChart {...common} stacked={stacked} />
        )}
      </div>
      {footer && <div className="border-t border-border px-5 py-3 text-[12.5px] text-muted-foreground">{footer}</div>}
    </Card>
  );
}

import type { ChartCardRange } from './ChartCard';

export interface CostPoint {
  day: string;
  Compute: number;
  Storage: number;
  Network: number;
}

const series = (labels: string[], base: [number, number, number], step: [number, number, number]): CostPoint[] =>
  labels.map((day, i) => ({
    day,
    Compute: Math.round(base[0] + step[0] * i + ((i * 37) % 11) * 4),
    Storage: Math.round(base[1] + step[1] * i + ((i * 13) % 7) * 2),
    Network: Math.round(base[2] + step[2] * i + ((i * 29) % 5) * 3),
  }));

const DAYS7 = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const DAYS30 = Array.from({ length: 30 }, (_, i) => `Day ${i + 1}`);
const WEEKS13 = Array.from({ length: 13 }, (_, i) => `Week ${i + 1}`);

/** Infrastructure cost by resource, per range. */
export const COST_BY_RANGE: Record<string, CostPoint[]> = {
  '7d': series(DAYS7, [180, 42, 120], [6, 1, 2]),
  '30d': series(DAYS30, [160, 40, 110], [2, 0.4, 1]),
  '90d': series(WEEKS13, [1100, 280, 760], [40, 6, 18]),
};

export const COST_RANGES: ChartCardRange[] = [
  { value: '7d', label: '7d', summary: { value: '$2,412', delta: { value: '+9.7%', direction: 'up', sentiment: 'negative' } } },
  { value: '30d', label: '30d', summary: { value: '$9,880', delta: { value: '+4.1%', direction: 'up', sentiment: 'negative' } } },
  { value: '90d', label: '90d', summary: { value: '$27,306', delta: { value: '−2.3%', direction: 'down', sentiment: 'positive' } } },
];

export interface TrafficRow {
  day: string;
  '00h': number;
  '03h': number;
  '06h': number;
  '09h': number;
  '12h': number;
  '15h': number;
  '18h': number;
  '21h': number;
}

/** Three-hour buckets of TRAFFIC_BY_RANGE, in display order. */
export const TRAFFIC_BUCKETS = ['00h', '03h', '06h', '09h', '12h', '15h', '18h', '21h'] as const;

const SHAPE = [0.18, 0.12, 0.3, 0.82, 1, 0.94, 0.7, 0.4];

/** Requests (thousands) per weekday and three-hour bucket: a heatmap for a ChartCard. */
export const TRAFFIC_BY_RANGE: Record<string, TrafficRow[]> = {
  '7d': DAYS7.map((day, d) => {
    const weekend = d >= 5 ? 0.45 : 1;
    const row = { day } as TrafficRow;
    TRAFFIC_BUCKETS.forEach((bucket, b) => {
      row[bucket] = Math.round((SHAPE[b] ?? 0) * weekend * (42 + ((d * 7 + b * 3) % 9)));
    });
    return row;
  }),
};

export const TRAFFIC_RANGES: ChartCardRange[] = [
  { value: '7d', label: 'Last 7 days', summary: { value: '4.8M requests', delta: { value: '+6.2%', direction: 'up', sentiment: 'positive' } } },
];

import { cn } from '@gntik-ai/ui';

/** Arrow shape of a change. */
export type DeltaDirection = 'up' | 'down' | 'flat';
/** Whether the change is good, bad or neither — independent of its direction (lower latency is good). */
export type DeltaSentiment = 'positive' | 'negative' | 'neutral';

export interface KpiDelta {
  /** Display text, e.g. "+12.4%". */
  value: string;
  direction: DeltaDirection;
  sentiment: DeltaSentiment;
  /** Comparison context, e.g. "vs. previous 24h". */
  note?: string;
}

const SENTIMENT_CLASS: Record<DeltaSentiment, string> = {
  positive: 'text-success-text',
  negative: 'text-destructive-text',
  neutral: 'text-muted-foreground',
};

const DIRECTION_TEXT: Record<DeltaDirection, string> = { up: 'Increased by', down: 'Decreased by', flat: 'Unchanged:' };
const SENTIMENT_TEXT: Record<DeltaSentiment, string> = { positive: 'favourable', negative: 'unfavourable', neutral: '' };

export interface TrendDeltaProps extends KpiDelta {
  className?: string;
}

/**
 * Mono delta with a triangle: the arrow follows `direction`, the colour follows `sentiment`.
 * Screen readers get the direction and sentiment in words.
 */
export function TrendDelta({ value, direction, sentiment, className }: TrendDeltaProps) {
  const sr = [DIRECTION_TEXT[direction], value, SENTIMENT_TEXT[sentiment] && `(${SENTIMENT_TEXT[sentiment]})`].filter(Boolean).join(' ');
  return (
    <span
      data-sentiment={sentiment}
      className={cn('inline-flex items-center gap-1 font-mono text-[12px] font-medium tabular-nums', SENTIMENT_CLASS[sentiment], className)}
    >
      <svg width="9" height="9" viewBox="0 0 10 10" aria-hidden className="shrink-0">
        {direction === 'up' && <path d="M5 1.5 9 8.5H1z" fill="currentColor" />}
        {direction === 'down' && <path d="M5 8.5 1 1.5h8z" fill="currentColor" />}
        {direction === 'flat' && <path d="M1 4h8v2H1z" fill="currentColor" />}
      </svg>
      <span aria-hidden>{value}</span>
      <span className="sr-only">{sr}</span>
    </span>
  );
}
